func loadPayment(ctx context.Context, db *sql.DB, id int64) (Payment, error) {
    var r struct{ ID int64; Name, Kind string; Card sql.NullString }
    if err := db.QueryRowContext(ctx, `SELECT id, name, kind, card_number
        FROM payment WHERE id = $1`, id).Scan(&r.ID, &r.Name, &r.Kind, &r.Card); err != nil {
        return nil, err
    }
    switch r.Kind {                              // discriminator -> concrete type
    case "card":
        return &CreditCardPayment{Payment: Payment{ID: r.ID, Name: r.Name}, CardNumber: r.Card.String}, nil
    default:
        return &Payment{ID: r.ID, Name: r.Name}, nil
    }
}
